package ai.eva.android.probe;
import android.accessibilityservice.*;import android.view.accessibility.*;import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.io.*;
/** User-enabled UI automation. All actions run on the accessibility main thread. */
public class PhoneAccessibility extends AccessibilityService {
 static final class StaleSnapshot extends IOException {StaleSnapshot(String message){super(message);}}
 static volatile PhoneAccessibility live;static volatile boolean armed;static volatile long generation;
 static final ExecutorService imageWorker=Executors.newSingleThreadExecutor();int visited;long scanDeadline;
 final Map<String,AccessibilityNodeInfo> nodes=new HashMap<>();long observedAt;volatile String snapshot="";String snapshotPackage="";int snapshotWindow=-1;
 protected void onServiceConnected(){if(Build.VERSION.SDK_INT>=33){AccessibilityServiceInfo info=getServiceInfo();info.flags|=AccessibilityServiceInfo.FLAG_INPUT_METHOD_EDITOR;setServiceInfo(info);}live=this;PhoneTaskService.restore(this);}
 volatile String foregroundPackage="";volatile int foregroundWindow=-1;volatile long windowRevision,observedRevision,lastUiEventAt;String emptyTreePackage="";long emptyTreeRevision=-1;
 public void onAccessibilityEvent(AccessibilityEvent e){lastUiEventAt=SystemClock.elapsedRealtime();if(e.getEventType()==AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED&&e.getPackageName()!=null){String pkg=e.getPackageName().toString();if(!pkg.equals(foregroundPackage)||foregroundWindow!=e.getWindowId()){foregroundPackage=pkg;foregroundWindow=e.getWindowId();windowRevision++;}}}
 AccessibilityNodeInfo readableRoot(){AccessibilityNodeInfo root=getRootInActiveWindow();if(root!=null)return root;java.util.List<AccessibilityWindowInfo> windows=getWindows();if(windows!=null)for(AccessibilityWindowInfo w:windows){if(w.getType()==AccessibilityWindowInfo.TYPE_APPLICATION&&(w.isActive()||w.isFocused())){root=w.getRoot();if(root!=null)return root;}}return null;}
 void observeAsync(CompletableFuture<JSONObject> result,boolean image,int attempt,long epoch){
  try{guard();if(epoch!=generation)throw new IOException("操作已取消");
   final JSONObject state=observe();final long revision=windowRevision;String pkg=state.optString("package");boolean empty=state.getJSONArray("nodes").length()==0;
   // Retry a newly encountered empty window once; known visual-only windows do not pay this delay on every action.
   if(empty&&attempt==0&&(!pkg.equals(emptyTreePackage)||emptyTreeRevision!=revision)){new Handler(getMainLooper()).postDelayed(()->observeAsync(result,image,attempt+1,epoch),120);return;}
   if(empty){emptyTreePackage=pkg;emptyTreeRevision=revision;}else{emptyTreePackage="";emptyTreeRevision=-1;}
   int labels=0;JSONArray rows=state.getJSONArray("nodes");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!row.optString("text").isEmpty()||!row.optString("description").isEmpty()||!row.optString("hint").isEmpty())labels++;}
   if(image||labels==0){CompletableFuture<JSONObject> shot=new CompletableFuture<>();shot.whenComplete((picture,error)->{
    try{if(epoch!=generation){result.completeExceptionally(new IOException("操作已取消"));return;}
     if(revision!=windowRevision||!state.optString("snapshot").equals(snapshot)){if(attempt<2){new Handler(getMainLooper()).post(()->observeAsync(result,image,attempt+1,epoch));return;}result.completeExceptionally(new IOException("页面仍在切换，请稍后 observe"));return;}
     if(error!=null){state.put("screenshotError",String.valueOf(error.getMessage()));state.put("instruction","页面树不足且截图不可用，请报告具体原因。");}
     else{for(Iterator<String> keys=picture.keys();keys.hasNext();){String key=keys.next();state.put(key,picture.get(key));}state.put("recognition","accessibility+vision");state.put("instruction","已附截图，不必立即再次 screenshot。按图像与屏幕尺寸换算 gesture 坐标；focusedInputAvailable 为 true 时可省略 node 调用 input。操作结果中已有新观察时直接使用。");}
     result.complete(state);
    }catch(Exception e){result.completeExceptionally(e);}
   });screenshot(shot,image?1920:1280);}else result.complete(state);
  }catch(Exception e){result.completeExceptionally(e);}
 }

 public void onInterrupt(){clearNodes();}
 public void onDestroy(){if(live==this){PhoneTaskReport.close(this);stopControl();clearNodes();live=null;PhoneTaskService.reason(this,"无障碍连接已断开，等待系统重连");}super.onDestroy();}
 static void stopControl(){armed=false;generation++;PhoneShell.cancel();PhoneAccessibility s=live;if(s!=null)new Handler(s.getMainLooper()).post(s::clearNodes);}
 void clearNodes(){for(AccessibilityNodeInfo n:nodes.values())n.recycle();nodes.clear();snapshot="";}
 void guard()throws Exception{if(!armed)throw new IOException("手机控制已停止，请在 Eva 的手机控制页开启");if(((KeyguardManager)getSystemService(KEYGUARD_SERVICE)).isKeyguardLocked())throw new IOException("手机已锁定，请解锁后继续");}
 JSONObject observe()throws Exception{guard();clearNodes();if(Build.VERSION.SDK_INT>=33)clearCache();AccessibilityNodeInfo root=readableRoot();observedAt=SystemClock.elapsedRealtime();snapshot=UUID.randomUUID().toString();observedRevision=windowRevision;snapshotWindow=root==null?-1:root.getWindowId();snapshotPackage=root==null?foregroundPackage:String.valueOf(root.getPackageName());JSONArray list=new JSONArray();visited=0;scanDeadline=SystemClock.elapsedRealtime()+180;if(root!=null){walk(root,list,0);root.recycle();}android.util.DisplayMetrics dm=getResources().getDisplayMetrics();return new JSONObject().put("snapshot",snapshot).put("expiresInMs",15000).put("package",snapshotPackage).put("width",dm.widthPixels).put("height",dm.heightPixels).put("nodes",list).put("focusedInputAvailable",focusedInputAvailable()).put("truncated",list.length()>=200||visited>=1500||SystemClock.elapsedRealtime()>scanDeadline).put("recognition",list.length()==0?"visual-fallback-needed":"accessibility").put("instruction","核对本次观察；操作返回新 snapshot 后直接使用，无须重复 observe。省略布尔字段为 false，enabled 默认 true。未找到目标时可截图或使用 App 搜索入口。");}
 void walk(AccessibilityNodeInfo n,JSONArray out,int depth)throws Exception{
  if(depth>30||out.length()>=200||++visited>1500||SystemClock.elapsedRealtime()>scanDeadline)return;
  String text=n.isPassword()?"[password]":clip(n.getText()),description=n.isPassword()?"":clip(n.getContentDescription()),hint=n.isPassword()?"":clip(n.getHintText());
  boolean meaningful=!text.isEmpty()||!description.isEmpty()||!hint.isEmpty()||n.isClickable()||n.isEditable()||n.isScrollable()||n.isCheckable();
  if(n.isVisibleToUser()&&meaningful){String id="n"+out.length();Rect bounds=new Rect();n.getBoundsInScreen(bounds);
   JSONObject row=new JSONObject().put("id",id).put("bounds",new JSONArray(new int[]{bounds.left,bounds.top,bounds.right,bounds.bottom}));
   if(!text.isEmpty())row.put("text",text);if(!description.isEmpty())row.put("description",description);if(!hint.isEmpty())row.put("hint",hint);
   if(n.getViewIdResourceName()!=null)row.put("resourceId",n.getViewIdResourceName());
   if(n.isClickable())row.put("clickable",true);if(n.isEditable())row.put("editable",true);if(n.isScrollable())row.put("scrollable",true);if(n.isCheckable())row.put("checked",n.isChecked());if(n.isSelected())row.put("selected",true);if(!n.isEnabled())row.put("enabled",false);
   out.put(row);nodes.put(id,AccessibilityNodeInfo.obtain(n));
  }
  for(int i=0;i<n.getChildCount()&&out.length()<200&&visited<1500&&SystemClock.elapsedRealtime()<=scanDeadline;i++){AccessibilityNodeInfo child=n.getChild(i);if(child!=null){walk(child,out,depth+1);child.recycle();}}
 }
 boolean focusedInputAvailable(){if(Build.VERSION.SDK_INT<33)return false;try{android.accessibilityservice.InputMethod m=getInputMethod();if(m==null||!m.getCurrentInputStarted()||m.getCurrentInputConnection()==null||m.getCurrentInputEditorInfo()==null)return false;validateEditor(m.getCurrentInputEditorInfo(),snapshotPackage);return true;}catch(Exception ignored){return false;}}

 String clip(CharSequence s){if(s==null)return "";String t=s.toString();return t.length()>500?t.substring(0,500):t;}
 void validSnapshot(JSONObject args)throws Exception{if(SystemClock.elapsedRealtime()-observedAt>15000||snapshot.isEmpty()||!snapshot.equals(args.optString("snapshot")))throw new StaleSnapshot("页面快照已失效，请先 observe");AccessibilityNodeInfo root=readableRoot();if(snapshotWindow==-1){if(observedRevision!=windowRevision)throw new StaleSnapshot("前台窗口已变化，请重新 observe");if(root!=null)root.recycle();return;}if(root==null)throw new StaleSnapshot("窗口正在切换，请重新 observe 获取截图与快照");boolean match=root.getWindowId()==snapshotWindow&&snapshotPackage.equals(String.valueOf(root.getPackageName()));root.recycle();if(!match)throw new StaleSnapshot("前台 App 已变化，请重新 observe");}
 JSONObject action(String action,JSONObject a)throws Exception{guard();if(action.equals("observe"))return observe();if(action.equals("back")||action.equals("home")){validSnapshot(a);boolean ok=performGlobalAction(action.equals("back")?GLOBAL_ACTION_BACK:GLOBAL_ACTION_HOME);clearNodes();return new JSONObject().put("dispatched",ok);}validSnapshot(a);if(action.equals("input")&&a.optString("node").isEmpty())return inputFocused(a.getString("text"));AccessibilityNodeInfo node=nodes.get(a.optString("node"));if(node==null||!node.refresh()||!node.isVisibleToUser())throw new StaleSnapshot("控件不可用，请重新 observe");if(node.isPassword())throw new IOException("密码框需用户手动输入");boolean ok=false;if(action.equals("click"))ok=actOnAncestor(node,AccessibilityNodeInfo.ACTION_CLICK);else if(action.equals("input")){String value=a.getString("text");if(value.length()>10000)throw new IOException("输入过长");Bundle b=new Bundle();b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);ok=node.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,b);}else if(action.equals("scroll"))ok=actOnAncestor(node,(a.optString("direction").equals("backward")||a.optString("direction").equals("up"))?AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD:AccessibilityNodeInfo.ACTION_SCROLL_FORWARD);else throw new IOException("未知操作");clearNodes();return new JSONObject().put("dispatched",ok).put("instruction","必须重新 observe 验证结果");}
 // Android's accessibility IME connection supports Unicode without a view-node ID.
 // It inserts at the current selection; it never presses Send/Enter or replaces the user's keyboard.
 JSONObject inputFocused(String text)throws Exception{
  guard();if(text.length()>10000)throw new IOException("输入过长");
  if(Build.VERSION.SDK_INT<33)throw new IOException("此系统不支持无控件编号输入，请使用可编辑节点");
  android.accessibilityservice.InputMethod method=getInputMethod();
  android.view.inputmethod.EditorInfo editor=method==null?null:method.getCurrentInputEditorInfo();
  if(method==null||!method.getCurrentInputStarted()||editor==null||method.getCurrentInputConnection()==null)throw new IOException("未检测到已聚焦的输入框，请先点击输入框并等待键盘出现，再 observe 后输入");
  validateEditor(editor,snapshotPackage);
  method.getCurrentInputConnection().commitText(text,1,null);clearNodes();
  return new JSONObject().put("dispatched",true).put("inputMethod","focused-editor").put("instruction","文字已提交到当前输入框，请观察核对。尚未执行发送。");
 }
 static void validateEditor(android.view.inputmethod.EditorInfo editor,String pkg)throws IOException{
  if(pkg.isEmpty()||!pkg.equals(editor.packageName))throw new IOException("当前输入框不属于快照中的 App，请重新 observe 确认焦点");
  int type=editor.inputType,kind=type&android.text.InputType.TYPE_MASK_CLASS,variation=type&android.text.InputType.TYPE_MASK_VARIATION;
  if(kind==android.text.InputType.TYPE_CLASS_TEXT&&(variation==android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD||variation==android.text.InputType.TYPE_TEXT_VARIATION_WEB_PASSWORD||variation==android.text.InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD)||kind==android.text.InputType.TYPE_CLASS_NUMBER&&variation==android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD)throw new IOException("密码框需用户手动输入");
  if(kind!=android.text.InputType.TYPE_CLASS_TEXT&&kind!=android.text.InputType.TYPE_CLASS_NUMBER&&kind!=android.text.InputType.TYPE_CLASS_PHONE&&kind!=android.text.InputType.TYPE_CLASS_DATETIME)throw new IOException("当前焦点不是可识别的文字输入框");
 }
 boolean actOnAncestor(AccessibilityNodeInfo start,int action){AccessibilityNodeInfo cursor=AccessibilityNodeInfo.obtain(start);try{for(int depth=0;cursor!=null&&depth<6;depth++){boolean eligible=action==AccessibilityNodeInfo.ACTION_CLICK?cursor.isClickable():cursor.isScrollable();if(cursor.isEnabled()&&eligible&&cursor.performAction(action))return true;AccessibilityNodeInfo parent=cursor.getParent();cursor.recycle();cursor=parent;}return false;}finally{if(cursor!=null)cursor.recycle();}}
 void gesture(JSONObject a,CompletableFuture<JSONObject> result){try{guard();validSnapshot(a);android.util.DisplayMetrics dm=getResources().getDisplayMetrics();float x=(float)a.getDouble("x"),y=(float)a.getDouble("y"),ex=(float)a.optDouble("endX",x),ey=(float)a.optDouble("endY",y);if(!Float.isFinite(x)||!Float.isFinite(y)||!Float.isFinite(ex)||!Float.isFinite(ey)||Math.min(x,ex)<0||Math.min(y,ey)<0||Math.max(x,ex)>=dm.widthPixels||Math.max(y,ey)>=dm.heightPixels)throw new IOException("坐标超出屏幕");Path path=new Path();path.moveTo(x,y);path.lineTo(ex,ey);long duration=Math.max(80,Math.min(1500,a.optLong("durationMs",250)));boolean started=dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,duration)).build(),new GestureResultCallback(){public void onCompleted(GestureDescription d){try{result.complete(new JSONObject().put("dispatched",true));}catch(Exception e){result.completeExceptionally(e);}}public void onCancelled(GestureDescription d){result.completeExceptionally(new IOException("手势被取消"));}},null);clearNodes();if(!started)throw new IOException("系统拒绝手势");}catch(Exception e){result.completeExceptionally(e);}}
 void screenshot(CompletableFuture<JSONObject> result){screenshot(result,1920);}
 // Private OCR path: retain original pixels, without JPEG/base64 round trips or gallery files.
 void captureBitmap(CompletableFuture<Bitmap> result){try{guard();final long epoch=generation;if(Build.VERSION.SDK_INT<30)throw new IOException("当前系统不支持无障碍截图");takeScreenshot(0,getMainExecutor(),new TakeScreenshotCallback(){public void onSuccess(ScreenshotResult r){imageWorker.execute(()->{Bitmap hardware=null,copy=null;try{guard();if(epoch!=generation)throw new IOException("操作已取消");hardware=Bitmap.wrapHardwareBuffer(r.getHardwareBuffer(),r.getColorSpace());if(hardware==null)throw new IOException("截图为空");copy=hardware.copy(Bitmap.Config.ARGB_8888,false);guard();if(epoch!=generation)throw new IOException("操作已取消");if(result.complete(copy))copy=null;}catch(Exception e){result.completeExceptionally(e);}finally{if(copy!=null)copy.recycle();if(hardware!=null)hardware.recycle();r.getHardwareBuffer().close();}});}public void onFailure(int code){result.completeExceptionally(new IOException("本地 OCR 取图失败："+code));}});}catch(Exception e){result.completeExceptionally(e);}}
 void screenshot(CompletableFuture<JSONObject> result,int maxDimension){try{guard();final long epoch=generation;if(Build.VERSION.SDK_INT<30)throw new IOException("当前系统不支持无障碍截图");takeScreenshot(0,getMainExecutor(),new TakeScreenshotCallback(){public void onSuccess(ScreenshotResult r){imageWorker.execute(()->{Bitmap hardware=null,copy=null;try{guard();if(epoch!=generation)throw new IOException("操作已取消");hardware=Bitmap.wrapHardwareBuffer(r.getHardwareBuffer(),r.getColorSpace());if(hardware==null)throw new IOException("截图为空");copy=hardware.copy(Bitmap.Config.ARGB_8888,false);int sw=copy.getWidth(),sh=copy.getHeight();if(Math.max(sw,sh)>maxDimension){float ratio=(float)maxDimension/Math.max(sw,sh);Bitmap small=Bitmap.createScaledBitmap(copy,Math.round(sw*ratio),Math.round(sh*ratio),true);copy.recycle();copy=small;}ByteArrayOutputStream out=new ByteArrayOutputStream();int width=copy.getWidth(),height=copy.getHeight();copy.compress(Bitmap.CompressFormat.JPEG,75,out);guard();if(epoch!=generation)throw new IOException("操作已取消");result.complete(new JSONObject().put("imageBytes",out.size()).put("imageWidth",width).put("imageHeight",height).put("screenWidth",sw).put("screenHeight",sh).put("imageUrl","data:image/jpeg;base64,"+android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP)));}catch(Exception e){result.completeExceptionally(e);}finally{if(copy!=null)copy.recycle();if(hardware!=null)hardware.recycle();r.getHardwareBuffer().close();}});}public void onFailure(int code){result.completeExceptionally(new IOException("截图失败，系统错误码 "+code+"；若页面受保护不可绕过，请用户手动处理"));}});}catch(Exception e){result.completeExceptionally(e);}}
}
